.eqz-page{

  background:#0c0a1f;
  color:#efeaff;
  font-family:'Source Sans 3','Segoe UI',system-ui,sans-serif;
  font-size:18px;
  line-height:1.55;
  -webkit-font-smoothing:antialiased;
}
/* full-bleed: escape the theme's content column */
.eqz-page{width:100vw;margin-left:calc(50% - 50vw);margin-right:calc(50% - 50vw);overflow-x:hidden}
.eqz-wrap{max-width:1120px;margin:0 auto;padding:0 24px}
.eqz-page *{box-sizing:border-box}
.eqz-page a{color:#5ee6ff;text-decoration:none}
.eqz-page a:hover{text-decoration:underline}
.eqz-page a:focus-visible,.eqz-page button:focus-visible{outline:2px solid #5ee6ff;outline-offset:3px}
.eqz-page h1,.eqz-page h2,.eqz-page h3{font-family:'Chakra Petch','Bahnschrift','Segoe UI',sans-serif;color:#efeaff;margin:0;text-wrap:balance;line-height:1.1}
.eqz-page p{margin:0}
.eqz-page code{font-family:'JetBrains Mono','Cascadia Code',Consolas,monospace;font-size:.9em;background:#1a1638;border:1px solid #2d2757;padding:.1em .4em;border-radius:4px;color:#c7a2ff}
.eqz-eyebrow{font-family:'JetBrains Mono','Cascadia Code',Consolas,monospace;font-size:12px;letter-spacing:.18em;text-transform:uppercase;color:#ff5fb8;margin-bottom:14px}

/* ---------------- top bar ---------------- */
.eqz-top{border-bottom:1px solid #2d2757;background:rgba(12,10,31,.85);backdrop-filter:blur(8px)}
.eqz-top .eqz-wrap{display:flex;align-items:center;justify-content:space-between;height:60px;gap:16px}
.eqz-brand{display:flex;align-items:center;gap:10px;font-family:'Chakra Petch','Bahnschrift','Segoe UI',sans-serif;font-weight:700;font-size:18px;letter-spacing:.04em;color:#efeaff!important}
.eqz-brand img{width:28px;height:28px}
.eqz-nav{display:flex;gap:26px;font-size:15px}
.eqz-nav a{color:#b8b0d9}
@media (max-width:640px){.eqz-nav{display:none}}

/* ---------------- hero ---------------- */
.eqz-hero{position:relative;padding:72px 0 64px;overflow:hidden;
  background:
    radial-gradient(60% 45% at 78% 22%,rgba(199,162,255,.22),transparent 70%),
    radial-gradient(40% 30% at 20% 90%,rgba(94,230,255,.10),transparent 70%),
    #0c0a1f}
.eqz-hero::after{content:"";position:absolute;left:-10%;right:-10%;bottom:-2px;height:38%;pointer-events:none;
  background:
    repeating-linear-gradient(90deg,rgba(255,95,184,.22) 0 1px,transparent 1px 84px),
    repeating-linear-gradient(0deg,rgba(255,95,184,.22) 0 1px,transparent 1px 34px);
  transform:perspective(420px) rotateX(62deg);transform-origin:50% 100%;
  -webkit-mask-image:linear-gradient(to top,rgba(0,0,0,.7),transparent);mask-image:linear-gradient(to top,rgba(0,0,0,.7),transparent)}
.eqz-hero .eqz-wrap{position:relative;z-index:1;display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:56px;align-items:center}
@media (max-width:860px){.eqz-hero .eqz-wrap{grid-template-columns:1fr}}
.eqz-hero h1{font-size:clamp(44px,7vw,76px);font-weight:700;letter-spacing:.02em;
  background:linear-gradient(180deg,#fff 0%,#c7a2ff 60%,#ff5fb8 100%);
  -webkit-background-clip:text;background-clip:text;color:transparent}
.eqz-hero .eqz-sub{font-family:'Source Sans 3','Segoe UI',system-ui,sans-serif;font-weight:400;font-size:clamp(19px,2.2vw,23px);line-height:1.4;color:#b8b0d9;max-width:34ch;margin:18px 0 10px}
.eqz-hero .eqz-sub2{color:#7d75a6;font-size:17px;margin:0 0 30px}
.eqz-hero .eqz-sub strong{color:#efeaff;font-weight:600}
.eqz-cta{display:flex;flex-wrap:wrap;gap:14px;align-items:center}
.eqz-btn{display:inline-flex;align-items:center;gap:10px;font-family:'Chakra Petch','Bahnschrift','Segoe UI',sans-serif;font-weight:700;font-size:17px;letter-spacing:.03em;
  padding:15px 26px;border-radius:6px;border:1px solid transparent;transition:transform .15s,box-shadow .15s;text-decoration:none!important}
.eqz-btn-primary{background:linear-gradient(135deg,#5ee6ff,#8ab4ff 55%,#ff5fb8);color:#0c0a1f!important;box-shadow:0 8px 30px rgba(94,230,255,.25)}
.eqz-btn-primary:hover{transform:translateY(-1px);box-shadow:0 12px 36px rgba(255,95,184,.3)}
.eqz-btn-ghost{color:#efeaff!important;border-color:#2d2757;background:rgba(26,22,56,.6)}
.eqz-btn-ghost:hover{border-color:#a98fe0}
.eqz-btn svg{width:18px;height:18px;fill:currentColor}
.eqz-meta{margin-top:16px;font-family:'JetBrains Mono','Cascadia Code',Consolas,monospace;font-size:13px;color:#7d75a6;display:flex;flex-wrap:wrap;gap:6px 18px}
.eqz-meta b{color:#b8b0d9;font-weight:600}

/* the DPS meter mock */
.eqz-mock{background:#1a1638;border:1px solid #2d2757;border-radius:10px;padding:16px 18px 18px;
  box-shadow:0 30px 80px rgba(0,0,0,.45),0 0 0 1px rgba(199,162,255,.06) inset;font-family:'JetBrains Mono','Cascadia Code',Consolas,monospace;font-size:13px}
.eqz-mock-hd{display:flex;justify-content:space-between;align-items:baseline;color:#b8b0d9;margin-bottom:12px;gap:12px}
.eqz-mock-hd b{color:#efeaff;font-weight:600}
.eqz-mock-hd .r{color:#5ee6ff;font-variant-numeric:tabular-nums}
.eqz-row{position:relative;display:grid;grid-template-columns:1fr auto;gap:0 12px;padding:8px 10px;margin:4px 0;border-radius:4px;overflow:hidden;background:rgba(12,10,31,.45)}
.eqz-row i{position:absolute;left:0;top:0;bottom:0;opacity:.28;border-radius:4px}
.eqz-row .nm,.eqz-row .val,.eqz-row .sub{position:relative}
.eqz-row .nm{color:#efeaff;font-weight:600}
.eqz-row .val{color:#efeaff;font-variant-numeric:tabular-nums;text-align:right}
.eqz-row .sub{grid-column:1/-1;color:#7d75a6;font-size:11.5px;margin-top:2px}
.eqz-row .miss{color:#ff5fb8}
.eqz-mock-ft{display:flex;justify-content:space-between;margin-top:12px;padding-top:10px;border-top:1px solid #2d2757;color:#7d75a6;font-size:11.5px}
.eqz-mock-ft .up{color:#7ee0a0}

/* ---------------- trust strip ---------------- */
.eqz-trust{border-top:1px solid #2d2757;border-bottom:1px solid #2d2757;background:#13102c}
.eqz-trust .eqz-wrap{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;padding:26px 24px}
@media (max-width:720px){.eqz-trust .eqz-wrap{grid-template-columns:1fr}}
.eqz-trust h3{font-size:15px;letter-spacing:.06em;text-transform:uppercase;color:#5ee6ff;margin-bottom:6px}
.eqz-trust p{color:#b8b0d9;font-size:16px}

/* ---------------- sections ---------------- */
.eqz-section{padding:80px 0}
.eqz-section + .eqz-section{border-top:1px solid #2d2757}
.eqz-section h2{font-size:clamp(28px,4vw,40px);font-weight:700;margin-bottom:12px}
.eqz-lede{color:#b8b0d9;max-width:62ch;font-size:19px;margin-bottom:40px}

.eqz-features{display:grid;grid-template-columns:repeat(2,1fr);gap:22px 40px}
@media (max-width:720px){.eqz-features{grid-template-columns:1fr}}
.eqz-feature{padding:22px 0 22px 22px;border-left:2px solid #2d2757;position:relative}
.eqz-feature::before{content:"";position:absolute;left:-2px;top:22px;width:2px;height:28px;background:#ff5fb8}
.eqz-feature h3{font-size:19px;margin-bottom:8px}
.eqz-feature p{color:#b8b0d9;font-size:17px;max-width:48ch}

.eqz-steps{counter-reset:step;display:grid;grid-template-columns:repeat(4,1fr);gap:26px}
@media (max-width:900px){.eqz-steps{grid-template-columns:repeat(2,1fr)}}
@media (max-width:520px){.eqz-steps{grid-template-columns:1fr}}
.eqz-step{background:#1a1638;border:1px solid #2d2757;border-radius:8px;padding:22px 20px 24px}
.eqz-step::before{counter-increment:step;content:counter(step);display:block;font-family:'Chakra Petch','Bahnschrift','Segoe UI',sans-serif;font-size:34px;font-weight:700;color:#5ee6ff;line-height:1;margin-bottom:12px}
.eqz-step h3{font-size:18px;margin-bottom:8px}
.eqz-step p{color:#b8b0d9;font-size:16px}
.eqz-note{margin-top:28px;padding:18px 22px;border-radius:8px;border:1px solid rgba(240,196,106,.35);background:rgba(240,196,106,.06);color:#b8b0d9;font-size:16px;max-width:80ch}
.eqz-note b{color:#f0c46a}

.eqz-two{display:grid;grid-template-columns:1fr 1fr;gap:48px}
@media (max-width:820px){.eqz-two{grid-template-columns:1fr}}
.eqz-two h3{font-size:20px;margin-bottom:10px}
.eqz-two p{color:#b8b0d9;font-size:17px;max-width:56ch}
.eqz-two p + p{margin-top:12px}

.eqz-releases{display:grid;gap:0;max-width:820px}
.eqz-release{display:grid;grid-template-columns:120px 1fr;gap:18px;padding:18px 0;border-top:1px solid #2d2757}
.eqz-release:last-child{border-bottom:1px solid #2d2757}
@media (max-width:560px){.eqz-release{grid-template-columns:1fr;gap:6px}}
.eqz-release .v{font-family:'JetBrains Mono','Cascadia Code',Consolas,monospace;color:#5ee6ff;font-weight:600}
.eqz-release .v small{display:block;color:#7d75a6;font-weight:400;margin-top:4px}
.eqz-release ul{margin:0;padding-left:18px;color:#b8b0d9;font-size:16px;list-style:disc}
.eqz-release li{margin:4px 0}
.eqz-tag{display:inline-block;font-family:'JetBrains Mono','Cascadia Code',Consolas,monospace;font-size:11px;letter-spacing:.08em;text-transform:uppercase;padding:2px 7px;border-radius:3px;margin-right:6px;vertical-align:middle}
.eqz-tag-new{background:rgba(126,224,160,.15);color:#7ee0a0}
.eqz-tag-fixed{background:rgba(94,230,255,.15);color:#5ee6ff}
.eqz-tag-changed{background:rgba(199,162,255,.15);color:#c7a2ff}
.eqz-more{margin-top:22px;font-size:16px}

/* ---------------- faq ---------------- */
.eqz-faq{display:grid;grid-template-columns:repeat(2,1fr);gap:30px 44px}
@media (max-width:720px){.eqz-faq{grid-template-columns:1fr}}
.eqz-faq h3{font-size:18px;margin-bottom:6px}
.eqz-faq p{color:#b8b0d9;font-size:16px;max-width:52ch}
.eqz-two .eqz-note{margin-top:16px}

/* ---------------- footer ---------------- */
.eqz-foot{border-top:1px solid #2d2757;background:#13102c;padding:40px 0 48px;font-size:15px;color:#7d75a6}
.eqz-foot .eqz-wrap{display:flex;flex-wrap:wrap;justify-content:space-between;gap:18px 32px}
.eqz-foot p{max-width:64ch}
.eqz-foot nav{display:flex;gap:22px;flex-wrap:wrap}
.eqz-foot nav a{color:#b8b0d9}
@media (prefers-reduced-motion:reduce){.eqz-btn{transition:none}}

/* the full-bleed wrapper is exactly one viewport wide; keep the page from scrolling sideways by a scrollbar width */
html:has(.eqz-page),body:has(.eqz-page){overflow-x:hidden}

/* ---------------- inner pages (guides, contact) ---------------- */
.eqz-narrow{max-width:820px}
.eqz-pagehead{padding-bottom:40px}
.eqz-pagehead h1{font-size:clamp(32px,5vw,52px);font-weight:700;margin-bottom:14px}
.eqz-toc{display:flex;flex-wrap:wrap;gap:10px 14px;font-family:'JetBrains Mono','Cascadia Code',Consolas,monospace;font-size:13px}
.eqz-toc a{padding:6px 12px;border:1px solid #2d2757;border-radius:999px;color:#b8b0d9}
.eqz-toc a:hover{border-color:#a98fe0;text-decoration:none;color:#efeaff}
.eqz-guide{padding:48px 0}
.eqz-guide h2{font-size:clamp(24px,3vw,32px);margin-bottom:16px}
.eqz-guide p{color:#b8b0d9;font-size:17px;max-width:70ch}
.eqz-guide p + p{margin-top:12px}
.eqz-guide ol{margin:0 0 16px;padding-left:22px;color:#b8b0d9;font-size:17px;max-width:70ch}
.eqz-guide li{margin:8px 0;padding-left:4px}
.eqz-guide li::marker{color:#5ee6ff;font-family:'JetBrains Mono','Cascadia Code',Consolas,monospace;font-weight:600}
.eqz-guide b{color:#efeaff;font-weight:600}
.eqz-contact-ways{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:8px}
@media (max-width:720px){.eqz-contact-ways{grid-template-columns:1fr}}
.eqz-contact-ways h3{font-size:16px;letter-spacing:.04em;text-transform:uppercase;color:#5ee6ff;margin-bottom:6px}
.eqz-contact-ways p{color:#b8b0d9;font-size:16px}
/* the Jetpack form sits in its own group block between two HTML blocks */
.eqz-formpage{padding:0 0 72px}
.eqz-formpage .wp-block-jetpack-contact-form{max-width:820px;margin:0 auto;padding:0 24px;display:grid;gap:16px}
.eqz-formpage .wp-block-jetpack-contact-form label,.eqz-formpage .jetpack-field-label__input{color:#b8b0d9!important;font-family:'Source Sans 3','Segoe UI',system-ui,sans-serif;font-size:15px;font-weight:600;letter-spacing:.02em}
.eqz-formpage .wp-block-jetpack-contact-form input:not([type=submit]),.eqz-formpage .wp-block-jetpack-contact-form textarea,.eqz-formpage .wp-block-jetpack-contact-form select{width:100%;background:#1a1638!important;color:#efeaff!important;border:1px solid #2d2757!important;border-radius:6px!important;padding:12px 14px!important;font-family:'Source Sans 3','Segoe UI',system-ui,sans-serif!important;font-size:16px!important}
.eqz-formpage .wp-block-jetpack-contact-form textarea{min-height:180px}
.eqz-formpage .wp-block-jetpack-contact-form input:focus,.eqz-formpage .wp-block-jetpack-contact-form textarea:focus,.eqz-formpage .wp-block-jetpack-contact-form select:focus{outline:2px solid #5ee6ff;outline-offset:2px}
.eqz-formpage .wp-block-jetpack-contact-form .wp-block-button__link,.eqz-formpage .wp-block-jetpack-contact-form button[type=submit]{background:linear-gradient(135deg,#5ee6ff,#8ab4ff 55%,#ff5fb8)!important;color:#0c0a1f!important;font-family:'Chakra Petch','Bahnschrift','Segoe UI',sans-serif!important;font-weight:700!important;font-size:17px!important;letter-spacing:.03em;padding:15px 26px!important;border-radius:6px!important;border:0!important;justify-self:start}
.eqz-formpage .contact-form-submission,.eqz-formpage .form-errors{color:#efeaff;max-width:820px;margin:0 auto;padding:0 24px}

/* WordPress.com: the theme paints the body white and adds a block gap between our wrappers */
body:has(.eqz-page){background:#0c0a1f}
.eqz-page{margin-block-start:0!important;margin-block-end:0!important}
.eqz-formpage .wp-block-jetpack-contact-form{display:grid!important}
.eqz-formpage .grunion-field-wrap{width:100%!important;max-width:none!important;flex:1 1 100%!important}
.eqz-formpage .wp-block-jetpack-contact-form{grid-template-columns:1fr!important}

/* ---------------- support ---------------- */
.eqz-support-ways{display:flex;flex-direction:column;align-items:flex-start;gap:14px;justify-content:center}
.eqz-support-note{color:#7d75a6!important;font-size:15px!important}

/* ---------------- screenshots ---------------- */
.eqz-shot{margin:0;border:1px solid #2d2757;border-radius:10px;overflow:hidden;background:#1a1638;box-shadow:0 30px 80px rgba(0,0,0,.45)}
.eqz-shot img{display:block;width:100%;height:auto}
.eqz-shot figcaption{padding:10px 14px;font-family:'JetBrains Mono','Cascadia Code',Consolas,monospace;font-size:12px;line-height:1.5;color:#7d75a6;border-top:1px solid #2d2757}
.eqz-band{padding:0 0 64px;background:#0c0a1f}
.eqz-gallery{display:grid;grid-template-columns:minmax(0,640px) minmax(0,1fr);gap:36px;align-items:center;margin-bottom:56px}
@media (max-width:820px){.eqz-gallery{grid-template-columns:1fr}}
.eqz-gallery-copy h3{font-size:22px;margin-bottom:10px}
.eqz-gallery-copy p{color:#b8b0d9;font-size:17px;max-width:46ch}

.eqz-screens{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
@media (max-width:820px){.eqz-screens{grid-template-columns:1fr}}
.eqz-screens .eqz-shot{display:block;color:inherit;text-decoration:none!important}
.eqz-screens .eqz-shot:hover{border-color:#a98fe0}
.eqz-screens figcaption{display:block}
.eqz-support-note b{color:#efeaff}
